<html lang="en">
<head>
  <meta charset="utf-8" />
  <meta name="viewport" content="width=device-width, initial-scale=1" />
  <title>Support Contact Form</title>
  <style>
    :root {
      color-scheme: dark;
      --bg: #0b1020;
      --surface: #111831;
      --surface-2: #17213f;
      --border: #2a3760;
      --border-focus: #86a8ff;
      --text: #e6ebff;
      --muted: #a7b3da;
