    @media (max-width: 760px) {
      main {
        padding-top: 4.5rem;
      }

      .page-shell {
        grid-template-columns: 1fr;
      }
    }

    @media (forced-colors: active) {
      :root {
        --bg: Canvas;
        --surface: Canvas;
        --surface-2: Canvas;
        --border: CanvasText;
        --border-focus: Highlight;
        --text: CanvasText;
        --muted: CanvasText;
        --accent: Highlight;
        --accent-strong: Highlight;
        --danger: Mark;
      }

      .form-card,
      input,
      button {
        forced-color-adjust: auto;
      }

      .skip-link:focus,
      input:focus,
      button:focus {
        box-shadow: none;
      }
    }
  </style>
</head>
<body>
  <a class="skip-link" href="#main-content">Skip to main content</a>
  <div id="app"></div>

  <script>
    function Field({ id, label, type, required, helperText, errorText, autocomplete, inputmode }) {
      const describedBy = [helperText ? `${id}-help` : "", `${id}-error`].filter(Boolean).join(" ");
      return `
        <div class="form-field">
          <label for="${id}">${label}${required ? '<span class="required-mark" aria-hidden="true">*</span>' : ""}</label>
          <input
            id="${id}"
            name="${id}"
            type="${type}"
            ${autocomplete ? `autocomplete="${autocomplete}"` : ""}
            ${inputmode ? `inputmode="${inputmode}"` : ""}
            ${required ? "required aria-required=\"true\"" : ""}
            ${describedBy ? `aria-describedby="${describedBy}"` : ""}
          />
          ${helperText ? `<p class="field-help" id="${id}-help">${helperText}</p>` : ""}
          <p class="field-error" id="${id}-error" aria-live="polite"></p>
        </div>
      `;
    }

    function SupportContactForm() {
      return `
        <main id="main-content">
          <div class="page-shell">
            <section class="hero" aria-labelledby="support-title">
              <h1 id="support-title">Contact Support</h1>
              <p class="lede">Send us a message and we will get back to you as soon as possible.</p>
            </section>

            <section class="form-card" aria-labelledby="contact-form-title">
              <h2 id="contact-form-title" style="margin:0 0 1rem; font-size:1.25rem;">Request assistance</h2>
              <form id="support-form" novalidate>
                ${Field({
                  id: "full-name",
                  label: "Full name",
                  type: "text",
                  required: true,
                  autocomplete: "name"
                })}
                ${Field({
                  id: "email-address",
                  label: "Email address",
                  type: "email",
                  required: true,
                  autocomplete: "email"
                })}
                ${Field({
                  id: "phone-number",
                  label: "Phone number",
                  type: "tel",
                  required: false,
                  helperText: "Use a format like +1 555 123 4567 or (555) 123-4567.",
                  autocomplete: "tel",
                  inputmode: "tel"
                })}
                <p class="form-status" id="form-status" aria-live="polite"></p>
                <button type="submit">Submit request</button>
              </form>
            </section>
          </div>
        </main>
      `;
    }

    document.getElementById("app").innerHTML = SupportContactForm();

    const form = document.getElementById("support-form");
    const status = document.getElementById("form-status");
    const fields = [
      { id: "full-name", label: "Full name", required: true, validator: value => value.trim() ? "" : "Please enter your full name." },
      { id: "email-address", label: "Email address", required: true, validator: value => value.trim() ? (/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(value.trim()) ? "" : "Enter a valid email address.") : "Please enter your email address." },
      { id: "phone-number", label: "Phone number", required: false, validator: value => value.trim() && !/^[+()\-\s\d]{7,}$/.test(value.trim()) ? "Enter a valid phone number or leave it blank." : "" }
    ];

    function setFieldError(id, message) {
      const input = document.getElementById(id);
      const error = document.getElementById(`${id}-error`);
      if (message) {
        input.setAttribute("aria-invalid", "true");
      } else {
        input.removeAttribute("aria-invalid");
      }
      error.textContent = message;
    }

    function validateField(field) {
      const input = document.getElementById(field.id);
      const message = field.validator(input.value);
      setFieldError(field.id, message);
      return !message;
    }

    form.addEventListener("submit", event => {
      event.preventDefault();
      const firstInvalid = fields.find(field => !validateField(field));

      if (firstInvalid) {
        status.textContent = "Please fix the highlighted fields and try again.";
        document.getElementById(firstInvalid.id).focus();
        return;
      }

      status.textContent = "Your request is ready to submit.";
      form.reset();
      fields.forEach(field => setFieldError(field.id, ""));
    });

    fields.forEach(field => {
      const input = document.getElementById(field.id);
      input.addEventListener("input", () => {
        if (input.getAttribute("aria-invalid") === "true") {
          validateField(field);
        }
      });
      input.addEventListener("blur", () => {
        if (field.required || input.value.trim()) {
          validateField(field);
        } else {
          setFieldError(field.id, "");
        }
      });
    });
  </script>
</body>
</html>
